package de.vw.mib.asl.framework.api.dsiproxy;public class DSIProxy {public int adds,removes;public boolean failAdd;public void addServiceStateListener(Class type,int n,DSIServiceStateListener listener){adds++;if(failAdd){failAdd=false;throw new RuntimeException("partial fixture listener");}}public void removeServiceStateListener(Class type,int n,DSIServiceStateListener listener){removes++;}}
